public abstract class Animal {
    public abstract void makeNoise();   // 欠实现
    public abstract void eat();         // 欠实现
}

// 抽象子类可以「接一部分活」，把责任往下推
public abstract class Canine extends Animal {
    @Override public void eat() {       // Canine 实现了 eat，Dog 不用再写
        System.out.println("犬科通用吃法");
    }
    // makeNoise 还没实现，继续欠着
}

// 第一个具体类必须补齐所有剩下的抽象方法
public class Dog extends Canine {
    @Override public void makeNoise() { System.out.println("汪汪"); }  // 必须写
    // eat 已由 Canine 实现，不必再写
}

