// Pool Puzzle 完整答案
interface Nose {
    public int iMethod();              // 抽象方法，分号结尾
}

abstract class Picasso implements Nose {
    public int iMethod() { return 7; } // 默认实现返回 7
}

class Acts extends Picasso {
    @Override public int iMethod() { return 5; }  // 覆盖返回 5
}

class Clowns extends Picasso { }       // 不覆盖，用 Picasso 的 7

public class Of76 extends Clowns {
    public static void main(String[] args) {
        Nose[] i = new Nose[3];         // 接口当数组类型！
        i[0] = new Acts();
        i[1] = new Clowns();
        i[2] = new Of76();
        for (int x = 0; x < 3; x++) {
            System.out.println(i[x].iMethod() + " " + i[x].getClass());
        }
    }
}
// 输出：
// 5 class Acts     （Acts 覆盖 iMethod 返回 5）
// 7 class Clowns   （没覆盖，用 Picasso 的 7）
// 7 class Of76     （Of76→Clowns→Picasso，没覆盖，返回 7）
